const templates = $('Fetch Onboarding Templates').all();
const project = $('Create Onboarding Project').first().json;
const user = $('Fetch User').first().json;
const companyId = project.company_id;
const projectId = project.id;
const ownerId = project.owner_id;

if (!templates.length) return [{ json: { sql: null, task_count: 0 } }];

const valueSets = templates.map(t => {
  const tmpl = t.json;
  const due = tmpl.days_offset !== null
    ? `NOW() + INTERVAL '${parseInt(tmpl.days_offset)} days'`
    : 'NULL';
  const assignee = tmpl.default_owner_role === 'new_user' ? user.id : ownerId;
  return `('${companyId}', '${projectId}', '${tmpl.task_title.replace(/'/g, "''")}', '${assignee}', 'todo', 'medium', ${due})`;
});

const sql = `INSERT INTO ops_tasks (company_id, project_id, title, owner_id, status, priority, due_date) VALUES ${valueSets.join(', ')}`;

return [{ json: { sql, task_count: templates.length } }];
